                    result[r, c] = 4
                else:
                    result[r, c] = 0
            else:  # rows 4-7 (folded pattern)
                if r % 2 == 0:  # rows 4, 6
                    if c in [0, 2, 4]:
                        result[r, c] = 4
                    else:
                        result[r, c] = 0
                else:  # rows 5, 7
                    result[r, c] = 0

    # TR (8x5): Similar but right-side adjustment
    for c in range(5):
        for r in range(8):
            if r <= 3:
                if c in [0, 2, 4]:
                    result[r, 7+c] = 4
                else:
                    result[r, 7+c] = 0
            else:
                if r % 2 == 0:
                    if c in [0, 2, 4]:
                        result[r, 7+c] = 4
                    else:
                        result[r, 7+c] = 0
                else:
                    result[r, 7+c] = 0

    # BL (3x6): Copy Demo 2 BL top 3 rows
    pattern_bl = np.array([
        [4, 0, 4, 0, 4, 0],
        [4, 0, 4, 0, 4, 4],
        [4, 0, 4, 0, 0, 0],
    ])
